(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.018-t*0.24)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.4, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.6, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.6+4)*40, 0.1, 1.4, 0.85],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.65+1)*50, 0.07, 2.2, 1.0]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    const wave2 = Math.sin(d*f*1.618-t*sp*0.78+0.5);
    aS += wave*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2 += wave2*w;
    iS2 += Math.sin(d*f*0.5-t*sp*0.4+3.0)*w;
  }
  const act = (aS+aS2*0.4)/8, inh = (iS+iS2*0.3)/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.06*Math.sin(t*0.15)+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.08-ang*2+t*0.8)*0.5)*0.3;
  const micro = Math.sin(sx*0.2+t*1.5)*Math.sin(sy*0.2-t*1.2)*0.15;
  const reaction = Math.tanh((act-inh*0.65+bg*0.3+spiral+micro)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.08-t*0.7)*Math.cos(sy*0.09+t*0.5)*0.3)*1.5)*0.3;
  const sharp = reaction>0.6?(reaction-0.6)*2.5:reaction<-0.6?(reaction+0.6)*2.5:0;
  const blend = reaction*0.6+cell*0.2+sharp*0.2, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,42,88],[12,78,118],[18,125,135],
    [45,165,148],[120,188,110],[195,195,65],
    [220,165,50],[215,115,55],[185,65,60],
    [140,35,55],[85,18,48],[40,10,40],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = 1.0+Math.pow(Math.abs(reaction),3)*0.3;
  const glow = Math.max(0, 1.0-Math.abs(reaction)*1.8)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*40))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*60))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*90))|0
  ];
}
